import { test, expect } from '@playwright/test';

test.describe('File Upload - File Name and Size Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should display file name and size when a file is selected', async ({ page }) => {
    // Intercept the file upload API call
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Locate and click the file input using getByRole
    const fileInput = page.getByRole('button', { name: /choose file/i });
    await fileInput.click();

    // Locate and select a file using getByLabel
    const fileInputLabel = page.getByLabel(/choose file/i);
    await fileInputLabel.click();

    // Locate and click the file using getByRole
    const fileInput = page.getByRole('button', { name: /choose file/i });
    await fileInput.click();

    // Wait for file name and size to appear
    const fileNameDisplay = page.getByText(/filename/i);
    const fileSizeDisplay = page.getByText(/size/i);

    await expect(fileNameDisplay).toBeVisible();
    await expect(fileSizeDisplay).toBeVisible();

    // Verify file name and size are displayed
    const fileName = await fileNameDisplay.textContent();
    const fileSize = await fileSizeDisplay.textContent();
    expect(fileName).toBe('example.pdf');
    expect(fileSize).toBe('1.2 MB');

    // Verify file name and size are visible in the UI
    const fileNameElement = page.getByText(fileName);
    const fileSizeElement = page.getByText(fileSize);
    await expect(fileNameElement).toBeVisible();
    await expect(fileSizeElement).toBeVisible();

    // Verify file name and size are displayed in the upload progress bar
    const progressBar = page.locator('[data-testid="upload-progress-bar"]');
    await expect(progressBar).toBeVisible();
  });

  test('should handle empty file selection and display error message', async ({ page }) => {
    // Intercept the file upload API call
    await page.route('**/api/upload', (route) => {
      route.abort();
    });

    // Locate and click the file input using getByRole
    const fileInput = page.getByRole('button', { name: /choose file/i });
    await fileInput.click();

    // Locate and select an empty file using getByLabel
    const fileInputLabel = page.getByLabel(/choose file/i);
    await fileInputLabel.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/file is empty/i);
    await expect(errorMessage).toBeVisible();

    // Verify file name and size are not displayed
    const fileNameDisplay = page.getByText(/filename/i);
    const fileSizeDisplay = page.getByText(/size/i);
    await expect(fileNameDisplay).not.toBeVisible();
    await expect(fileSizeDisplay).not.toBeVisible();

    // Verify error message is visible in the UI
    await expect(errorMessage).toBeVisible();
  });
});
